/**
 * Engine — reads CONFIG, loads components, renders & animates.
 * DO NOT edit this file for customization. Edit config.js only.
 */

// ── Theme ────────────────────────────────────────────────────────
let currentMode = (CONFIG.defaultMode || "dark");

function applyTheme(mode) {
  currentMode = mode;
  const root = document.documentElement;
  const c = CONFIG.colors;

  root.style.setProperty("--primary", c.primary || "#ff69b4");
  root.style.setProperty("--accent", c.accent || "#15a1ed");

  const theme = c[mode] || c.dark || {};
  root.style.setProperty("--bg", theme.background || "#1a1a2e");
  root.style.setProperty("--text", theme.text || "#ffffff");
}

// ── Script Loader ────────────────────────────────────────────────
function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = src;
    s.onload = resolve;
    s.onerror = () => reject(new Error("Component not found: " + src));
    document.head.appendChild(s);
  });
}

// ── Cute Sticker Stage ──────────────────────────────────────────
let stickerIndex = -1;

function initStickers() {
  const stickers = Array.isArray(CONFIG.stickers) ? CONFIG.stickers : [];
  if (!stickers.length) return;

  // Preload sticker GIFs
  stickers.forEach((src) => {
    const pre = new Image();
    pre.src = src;
  });

  const stage = document.createElement("div");
  stage.id = "sticker-stage";
  const img = document.createElement("img");
  img.id = "sticker-img";
  img.alt = "cute sticker";
  img.src = stickers[0];
  stage.appendChild(img);
  document.body.appendChild(stage);
}

window.setNextSticker = function (tl, hide) {
  const stickers = Array.isArray(CONFIG.stickers) ? CONFIG.stickers : [];
  const stage = document.getElementById("sticker-stage");
  const img = document.getElementById("sticker-img");
  if (!stage || !img || !stickers.length) return;

  if (hide) {
    tl.to(stage, { opacity: 0, scale: 0.85, duration: 0.3 }, "<");
    return;
  }

  stickerIndex = (stickerIndex + 1) % stickers.length;
  const nextSrc = stickers[stickerIndex];

  tl.call(() => {
    img.src = nextSrc;
    gsap.fromTo(
      stage,
      { opacity: 0.6, scale: 0.85 },
      { opacity: 1, scale: 1, duration: 0.4, ease: "back.out(1.7)" }
    );
  });
};

function createMusicToggle(audio) {
  const btn = document.createElement("button");
  btn.id = "music-toggle";
  btn.type = "button";
  btn.title = "Putar / Matikan Musik";
  btn.textContent = audio && !audio.paused ? "🔊" : "🔇";

  let userMuted = false;

  if (audio) {
    audio.addEventListener("play", () => {
      btn.textContent = "🔊";
    });
    audio.addEventListener("pause", () => {
      btn.textContent = "🔇";
    });
  }

  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!audio) return;
    if (audio.paused) {
      userMuted = false;
      audio.play().catch(() => {});
    } else {
      userMuted = true;
      audio.pause();
    }
  });

  document.body.appendChild(btn);
  return () => userMuted;
}

function createRestartButton() {
  const btn = document.createElement("button");
  btn.id = "restart-btn";
  btn.type = "button";
  btn.title = "Ulang dari Awal";
  btn.textContent = "🔄";
  btn.style.display = "none";
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    window.location.reload();
  });
  document.body.appendChild(btn);

  window.showRestartButton = () => {
    btn.style.display = "flex";
  };
}

// ── Main ─────────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", async () => {
  applyTheme(currentMode);
  initStickers();

  // Set music source
  const audio = document.querySelector(".song");
  if (audio && CONFIG.music) {
    audio.querySelector("source").src = CONFIG.music;
    audio.load();
  }
  const isUserMuted = createMusicToggle(audio);
  createRestartButton();

  // Determine unique component types
  const types = [...new Set(CONFIG.sections.map((s) => s.type))];

  // Dynamically load component scripts
  for (const type of types) {
    try {
      await loadScript(`./script/components/${type}.js?v=20261117`);
    } catch (e) {
      console.warn(e.message);
    }
  }

  // Render all sections
  const container = document.querySelector(".container");
  const rendered = [];

  CONFIG.sections.forEach((section) => {
    const comp = window.Components && window.Components[section.type];
    if (!comp) {
      console.warn(`Component "${section.type}" not found, skipping.`);
      return;
    }
    const el = comp.render(container, section, CONFIG);
    rendered.push({ el, comp, section });
  });

  // Auto-play music immediately (with iOS/mobile tap fallback if browser blocks autoplay)
  if (audio) {
    const unlockEvents = ["click", "touchend"];
    const unlockAudio = () => {
      if (isUserMuted()) return;
      audio.play().then(() => {
        unlockEvents.forEach((evt) => document.removeEventListener(evt, unlockAudio));
      }).catch(() => {});
    };

    audio.play().catch(() => {
      unlockEvents.forEach((evt) => document.addEventListener(evt, unlockAudio, { passive: true }));
    });
  }
  buildTimeline(rendered);
});

// ── Timeline Builder ─────────────────────────────────────────────
function buildTimeline(rendered) {
  const tl = gsap.timeline();

  tl.to(".container", { duration: 0.6, visibility: "visible" });

  // Track deferred exits for overlay components
  let deferredExits = [];

  rendered.forEach(({ el, comp, section }, i) => {
    const isOverlay = comp.overlay === true;

    // Flush deferred exits before non-overlay sections
    if (!isOverlay && deferredExits.length > 0) {
      deferredExits.forEach((fn) => fn());
      deferredExits = [];
    }

    // Switch cute sticker for non-overlay sections (hide during countdown & profile photo)
    if (!isOverlay) {
      window.setNextSticker(tl, section.type === "profile" || section.type === "countdown");
    }

    // Animate
    comp.animate(tl, el, CONFIG);

    // Handle exit lifecycle
    if (comp.exit) {
      const next = rendered[i + 1];
      const nextIsOverlay = next && next.comp.overlay === true;

      if (nextIsOverlay) {
        deferredExits.push(() => comp.exit(tl, el));
      } else if (!isOverlay) {
        comp.exit(tl, el);
      }
    }
  });

  // Flush remaining
  deferredExits.forEach((fn) => fn());

  // Setup replay
  const replayBtn = document.getElementById("replay");
  if (replayBtn) {
    replayBtn.addEventListener("click", () => {
      stickerIndex = -1;
      tl.restart();
    });
  }
}
